# attach fwshift-web-sl: 10.30.1.0/24
G2=$(nsg 'fwshift-web-sl') || exit 1
# attach fwshift-app-subnet-members: 10.30.2.0-10.30.2.29 10.30.2.33-10.30.2.255
G3=$(nsg 'fwshift-app-subnet-members') || exit 1
# attach fwshift-app-nsg: 10.30.2.30-10.30.2.32
G4=$(nsg 'fwshift-app-nsg') || exit 1
# attach fwshift-db-sl: 10.30.3.0/24
G5=$(nsg 'fwshift-db-sl') || exit 1
# attach fwshift-mgmt-subnet: 10.30.9.0/24
